<?php
require __DIR__.'/bootstrap.php';
use Illuminate\Support\Facades\{Auth,DB};
use App\Models\{User,Product,PurchaseOrder,Supplier,GoodsReceipt,Expense,InventoryReturn};
$file=$dc17Root.'/evidence/supplier-return.json';$e=is_file($file)?json_decode(file_get_contents($file),true):[];if(($e['status']??'')==='PASS'){echo "Supplier return evidence retained.\n";exit;}
$account=json_decode(file_get_contents($dc16Root.'/accounts.json'),true)['control'];Auth::setUser(User::withoutGlobalScopes()->findOrFail($account['user_id']));
$save=function()use(&$e){dc17Evidence('supplier-return',$e);};$p=Product::findOrFail(302);$supplier=Supplier::firstOrFail();$orders=app(App\Services\PurchaseOrderService::class);
if(!isset($e['po_id'])){$po=$orders->create(['supplier_id'=>$supplier->id,'warehouse_id'=>6,'ordered_at'=>today()->toDateString(),'currency'=>'EUR','status'=>'ordered','notes'=>'DC17 supplier return acceptance','items'=>[['product_id'=>$p->id,'description'=>$p->name,'unit'=>'pcs','quantity'=>2,'unit_price'=>2]]]);$e['po_id']=$po->id;$save();}
$po=PurchaseOrder::with('items')->findOrFail($e['po_id']);
if(!isset($e['receipt_id'])){$orders->receive($po,['received_at'=>today()->toDateString(),'items'=>[['id'=>$po->items->first()->id,'quantity'=>2]],'idempotency_key'=>'dc17-supplier-return-receipt']);$e['receipt_id']=GoodsReceipt::where('purchase_order_id',$po->id)->value('id');$save();}
$receipt=GoodsReceipt::with('items')->findOrFail($e['receipt_id']);$matching=app(App\Services\SupplierInvoiceMatchingService::class);
if(!isset($e['bill_id'])){$bill=$matching->create(['supplier_id'=>$supplier->id,'purchase_order_id'=>$po->id,'vendor_name'=>$supplier->name,'vendor_business_number'=>'TEST-DC17-SUPPLIER-'.$supplier->id,'document_type'=>'purchase_invoice','document_number'=>'DC17-SUPPLIER-RETURN','source_type'=>'domestic','asset_treatment'=>'ordinary','category'=>'inventory','business_purpose'=>'DC17 synthetic receipt and return acceptance','invoice_date'=>today()->toDateString(),'supply_date'=>today()->toDateString(),'received_date'=>today()->toDateString(),'due_date'=>today()->addDays(21)->toDateString(),'currency'=>'EUR','exchange_rate'=>1,'net_amount'=>4,'vat_rate'=>0,'vat_amount'=>0,'vat_treatment'=>'non_vat','input_vat_eligible'=>false,'deductible_vat_amount'=>0,'goods_receipt_ids'=>[$receipt->id],'items'=>[['purchase_order_item_id'=>$po->items->first()->id,'product_id'=>$p->id,'description'=>$p->name,'quantity'=>2,'unit'=>'pcs','unit_price'=>2,'vat_rate'=>0]]]);$e['bill_id']=$bill->id;$save();}
$bill=$matching->approve(Expense::findOrFail($e['bill_id']),'DC17 verified two received units and supplier source invoice');$returns=app(App\Services\InventoryReturnService::class);
if(!isset($e['return_id'])){$r=$returns->create(['type'=>'supplier','supplier_id'=>$supplier->id,'purchase_order_id'=>$po->id,'goods_receipt_id'=>$receipt->id,'financial_resolution'=>'supplier_credit','financial_amount'=>2,'currency'=>'EUR','reference_number'=>'DC17-SUPPLIER-CREDIT','reason'=>'One synthetic unit returned for credit after source review','idempotency_key'=>'dc17-supplier-return','items'=>[['product_id'=>$p->id,'goods_receipt_item_id'=>$receipt->items->first()->id,'warehouse_id'=>6,'quantity'=>1,'condition'=>'sellable']]]);$e['return_id']=$r->id;$e['quantity_before_return']=$p->fresh()->quantity;$save();}
$r=InventoryReturn::findOrFail($e['return_id']);if($r->status==='draft')$r=$returns->submit($r);if($r->status==='submitted')$r=$returns->approve($r);$r=$returns->complete($r);
$journals=DB::table('journal_entries')->count();$movements=DB::table('stock_movements')->count();$credit=$r->supplier_credit_expense_id;$returns->complete($r);
$reconciliation=app(App\Services\AccountingService::class)->reconciliation(false);
$e['checks']=['completed'=>$r->status==='completed','quantity_once'=>(float)$p->fresh()->quantity===(float)$e['quantity_before_return']-1,'one_credit'=>$credit!==null&&Expense::find($credit)?->status==='posted','original_bill_unchanged'=>$bill->fresh()->status==='posted'&&(float)$bill->gross_amount===4.0,'credit_value'=>(float)Expense::find($credit)?->gross_amount===2.0,'retry_no_extra_journal'=>DB::table('journal_entries')->count()===$journals,'retry_no_extra_movement'=>DB::table('stock_movements')->count()===$movements,'all_controls_reconciled'=>$reconciliation['all_reconciled']];
$e['credit_id']=$credit;$e['status']=in_array(false,$e['checks'],true)?'FAIL':'PASS';$e['reconciliation']=$reconciliation;$save();echo 'Supplier return: '.$e['status']."\n";if($e['status']!=='PASS')exit(2);
